#!/usr/bin/env python3
"""Offline comparison of saved, unretouched native canyon captures."""
from pathlib import Path
import json, re
ROOT=Path(__file__).resolve().parents[1]
r=ROOT/'docs/reports/canyon-composition'
def read(name):
 p=r/name
 return p.read_text() if p.exists() else ''
checks={n:('PASS' if ('PASS' in read(n+'.log') or '100% tests passed' in read(n+'.log')) and 'FAIL' not in read(n+'.log') else 'pending / failed') for n in ['geometry-tests','graphics-tests','occlusion-tests','gameplay-tests']}
def fields(text,tag):
 m=re.search(tag+r' (.*)',text)
 return dict(re.findall(r'(\w+)=([^\s]+)',m.group(1))) if m else {}
geometry=fields(read('geometry-tests.log'),'GEOMETRY')
bench={mode:fields(read('benchmark-'+mode+'.log'),'BENCHMARK') for mode in ['legacy','current']}
render={mode:fields(read('benchmark-'+mode+'.log'),'CANYON_RENDER:') for mode in ['legacy','current']}
remaining=[
 'Visual acceptance is not complete. Ground-level wall runs can still reveal the fixed room outline; some upper shelves remain too continuous.',
 'Exact composition is not matched: the reference has an unknown floor/seed and arranged objects. Existing playable footprints and boulder positions remain fixed by instruction.',
 'Some boulders still have regular lower footprints and some cliff facets follow the source lattice. These are visible in the native comparisons.',
 'Cliff plants are less densely clustered than the reference in some views. Green native assets remain in use.',
 'Visual and canonical physical rock profiles differ. Canonical navigation/projectile/flying-actor height volumes were not redesigned.',
 'WASM verification remains waived. No claim of pixel identity or full visual acceptance is made.'
]
measurements={'base_commit':'09cd526','working_tree':'uncommitted','checks':checks,'geometry':geometry,'benchmark':bench,'render':render,'capture':{'zoom_percent':160,'projection':'perspective','fov':45,'resolution':[1440,900],'seed':1866,'frame':120,'matching_scope':'Same native scene flags before/after. Reference camera pose and seed unavailable.'},'performance_scope':'One paired native 240-frame stress observation, same executable and assets, enabled0 legacy versus current geometry. Not a comparison against the immediately preceding commit, not ordinary-play FPS, not statistical evidence of a speedup. Geometry-test timings are startup CPU observations, with no formal before/after isolation.','remaining':remaining,'visual_acceptance':'partial; not an exact reference match'}
(r/'measurements.json').write_text(json.dumps(measurements,indent=2)+'\n')
css='''*{box-sizing:border-box}body{margin:0;background:#171c20;color:#eee2cc;font:17px/1.65 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:40px 28px}h1{font-size:clamp(30px,4vw,58px);line-height:1.1}h2{margin-top:46px;color:#edb879}h3{color:#dfb984}p,li{max-width:1050px}a{color:#7bd0bf}code,pre{background:#232d31;border-radius:6px}code{padding:3px 6px}pre{padding:20px;overflow:auto}img{display:block;width:100%;height:auto}figure{margin:0}figcaption{padding:10px 0;color:#baaf9f;font-size:14px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}.note{border-left:4px solid #d2934f;background:#302b24;padding:18px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:13px;border-bottom:1px solid #35434a}th{color:#e6b97a}summary{cursor:pointer;color:#7bd0bf}.compare{position:relative;overflow:hidden;--split:50%}.compare .before{position:absolute;inset:0;clip-path:inset(0 calc(100% - var(--split)) 0 0)}.divider{position:absolute;inset:0 auto 0 var(--split);border-left:2px solid white}.slider{display:flex;align-items:center;gap:12px;padding:15px 0}.slider input{width:70%}.eyebrow{color:#7bd0bf;text-transform:uppercase;letter-spacing:.12em;font-size:13px}@media(max-width:700px){main{padding:22px 15px}.pair{grid-template-columns:1fr}}'''
h='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DeathWard · Canyon contour correction</title><style>'''+css+'''</style><main><div class="eyebrow">DeathWard · Canyon contour correction · November 2026</div><h1>Independent rock contours.<br>Fixed gameplay boundaries.</h1><p class="note"><b>Visual acceptance remains partial.</b> This pass changes the mesh rules rather than only lowering heights. The remaining regular wall runs are visible below. Passing geometry and gameplay checks does not establish a visual match.</p><p>The previous pass was committed as <code>09cd526</code>. This working-tree correction preserves playable footprints, collision, room connections and camera settings. Every game image is a native capture; there is no paint-over, recoloring or generated comparison image.</p><h2>Target versus current game</h2><p>Native camera: 160% zoom, perspective, 45° FOV, 1440 × 900. The supplied reference also labels 160%; its seed, player position and camera pose are unavailable. These comparisons assess visual characteristics, rather than claiming identical scene composition.</p>'''
for name,title in [('works','Open combat room'),('combat','Connected trail and surrounding formations'),('power','Quiet room with supported upper vegetation')]:
 h+=f'<h3>{title}</h3><div class="pair"><figure><a href="target.png"><img src="target.png" alt="Supplied visual specification"></a><figcaption>Supplied target · original image.</figcaption></figure><figure><a href="final-{name}.png"><img src="final-{name}.png" alt="Current native {name} scene at 160 percent zoom"></a><figcaption>Current native capture · <a href="final-{name}.log">Log</a></figcaption></figure></div>'
h+='''<h2>Matched before/after captures</h2><p>Same seed, scene, frame count and camera. Left side shows committed pass 09cd526; right side shows this correction. The captured FPS labels are incidental and are not a controlled performance comparison.</p>'''
for name in ['works','combat']:
 h+=f'<article><h3>{name.capitalize()}</h3><div class="compare"><img src="final-{name}.png" alt="Current pass"><div class="before"><img src="before-{name}.png" alt="Committed previous pass"></div><div class="divider"></div></div><label class="slider">Before / after<input aria-label="Compare {name}" type="range" min="0" max="100" value="50"></label></article>'
h+='''<h2>Diagnosis and algorithm changes</h2><p>The canonical generator still builds the expedition floor and its solid terrain field. <code>CanyonAppearance</code> creates a separate cosmetic triangle mesh. <code>CanyonScene</code> packages its caps and walls into render chunks; <code>WesternScene</code> places existing native models. Canonical collision, roads, rivers, passage sockets and encounter logic are outside this correction.</p><div class="scroll"><table><tr><th>Artifact</th><th>Previous cause</th><th>Correction</th></tr><tr><td>Parallel terrace ribbons</td><td>One distance-from-floor scalar, cut at successive integer thresholds.</td><td>Independent domain-warped erosion fields for each shelf. Nested masks prevent crossing; ledges may terminate or merge locally. Local widths, contours and rises vary independently.</td></tr><tr><td>Constant layer heights</td><td>One global elevation per band.</td><td>Coarse geological planes vary base height and each rise. Variation is spatially coherent and controlled by height_variation; top surfaces remain broad, with restrained fine facets.</td></tr><tr><td>Upper edges inherit the floor outline</td><td>Upper and lower contour points came from the same source cells.</td><td>Upper rock vertices recess inward using the floor-distance gradient and coherent erosion. Ground-contact vertices stay fixed. Independent spatial bins follow displaced triangles for height, aiming and occlusion; render order stays stable.</td></tr><tr><td>Uniform boulder bases / pointed roofs</td><td>Fixed base elevation plus narrow original relief.</td><td>Detached rocks use a nonlinear relief profile independent of cliff-base elevation, a smaller chamfer, and their original footprints.</td></tr><tr><td>Strong yellow/orange layering</td><td>Cap texture bleed plus separate saturated cap/face palettes.</td><td>A closer, muted sandstone palette for cap and face; shared lighting, shadows and post-processing remain intact.</td></tr><tr><td>Evenly scattered decoration</td><td>Uniform acceptance of random candidates.</td><td>Coherent sheltered-pocket density modulates terrain-aware candidates; larger debris is allowed at cliff bases. Existing green leaves, bushes, trees, flowering cacti and golden grass remain.</td></tr></table></div><p><code>composition_strength</code> controls a static scenic framing bias baked along the normal world-view axis. It does not read the live camera or move cliffs when the player rotates or moves. Set it to 0 to disable that bias. Decorative terrain still extends beyond the playable floor.</p>
<h2>Visual assessment and architectural limit</h2><ul><li>Steep faces and broad caps remain, rather than broad triangular embankments.</li><li>Upper ledges break into more local formations; the same number of shelves no longer wraps every room at one fixed spacing.</li><li>Some runs at ground level still reveal the original room boundary. This criterion is not fully satisfied.</li><li>The reference has more deliberately composed isolated masses and vegetation pockets. Fixed boulder footprints and the unknown source layout prevent literal composition matching.</li><li>Some clipped facets and boulder bases remain more regular than the reference.</li></ul><p>For a stronger architectural departure, replace the remaining continuous scenic rim with individually seated polygonal rock masses, clipped to the canonical non-playable mask, and bridge their bases with a low erosion skirt. Its contour model and spatial index would be independent of the source lattice. The current correction supplies independent shelf fields and triangle indexing, but does not implement that full rock-mass union system. The canonical floor contact would still have to remain fixed.</p>
<h2>Regression evidence</h2><div class="scroll"><table><tr><th>Suite</th><th>Status</th><th>Log</th></tr>'''
for n,status in checks.items():h+=f'<tr><td>{n}</td><td>{status}</td><td><a href="{n}.log">Evidence</a></td></tr>'
h+='''</table></div><p>CPU checks cover twelve maps, six seeds, all river categories, deterministic geometry/decorations, unchanged canonical hashes, floor cells and sampled physical traces, clear roads and supported vegetation, config rejection and rollback. A new regression exercises height/ray/support queries for a triangle displaced into another source cell. GPU checks compare actual rendered mesh rays across five seeds and both themes. Occlusion checks exercise native fading, outlines and firing. Road, river, generated-floor and room-graph suites are rerun. The prior full floor-progression run remains archived; its gameplay code is unchanged.</p><pre>'''+json.dumps(geometry,indent=2)+'''</pre><p>A native mesh-ray failure during iteration exposed displaced geometry extending beyond the source field at its outer edge. The correction pins that outer strip; the final GPU suite is the evidence. The occlusion fixture also explicitly selects a visible obstruction that is physically solid in both test views before checking that fading preserves it. Physical obstruction is not inferred from visual height.</p>
<h2>Performance observation</h2><p>One 240-frame paired native stress run, same final executable/assets, original legacy terrain (<code>enabled 0</code>) versus this pass. This is not an isolated comparison against commit 09cd526 and is not ordinary gameplay FPS. A single WSL pair does not establish a general performance gain. Additional mesh indexing and CPU preprocessing are startup costs; the native geometry-test timing is recorded above.</p><div class="scroll"><table><tr><th>Metric</th><th>Legacy</th><th>Current</th></tr>'''
if all(bench.values()):
 for key in ['mean_ms','p95_ms','draw_ms','present_ms']:
  h+=f'<tr><td>{key}</td><td>{bench["legacy"].get(key,"—")}</td><td>{bench["current"].get(key,"—")}</td></tr>'
h+='</table></div>'
for mode,d in render.items():
 if d:h+=f'<p>{mode}: {d.get("triangles","?")} terrain triangles; {d.get("chunks","?")} chunks; {d.get("instances","?")} scenery instances.</p>'
h+='''<p><a href="benchmark-legacy.log">Legacy log</a> · <a href="benchmark-current.log">Current log</a> · <a href="measurements.json">Parsed measurements</a> · <a href="native-build.log">Build log</a></p><h2>Configuration, changed files and rollback</h2><p><code>assets/visual/canyon.cfg</code> controls nominal first elevation, maximum height, height/silhouette variation, shelf width/count, facets, density by terrain category, extent and budgets. <code>composition_strength</code> is new. Heights below the maximum vary locally; minimum_height is the nominal first elevation, rather than a strict minimum at every eroded edge. Restart after edits. No new model or texture dependency was added by this pass.</p><p>Source changes: <code>CanyonAppearance.hpp/.cpp</code>, <code>CanyonScene.cpp</code>, the visual config, and geometry/occlusion tests. Report generation: <code>scripts/canyon-composition-report.py</code>. Room generation, camera, UI, player controls, combat and projectile code are unchanged.</p><pre>./build/deathward --expedition --theme canyon --style original

# Restore original geometry/dressing for comparison
DEATHWARD_CANYON_CONFIG=assets/visual/canyon-legacy.cfg ./build/deathward</pre><h2>Remaining work</h2><ul>'''
for gap in remaining:h+='<li>'+gap+'</li>'
h+='''</ul><p><a href="../canyon-reference-match/index.html">Committed prior pass and native foliage library</a></p><details><summary>Discarded intermediate captures</summary><p>The last candidate moved upper formations closer to a lower boundary ledge. It made the stacked bands more conspicuous and was rejected; the source and executable were restored to the tested pass.</p>'''
for name in ['pass1-works','pass2-works','pass3-works','candidate-works','candidate-power']:
 h+=f'<figure><a href="{name}.png"><img loading="lazy" src="{name}.png" alt="Discarded {name}"></a><figcaption>{name} · retained for comparison, not final.</figcaption></figure>'
h+='''</details></main><script>document.querySelectorAll('.slider input').forEach(e=>e.addEventListener('input',()=>e.closest('article').querySelector('.compare').style.setProperty('--split',e.value+'%')));</script></html>'''
(r/'index.html').write_text(h)
print(json.dumps({'checks':checks,'visual_acceptance':'partial'},indent=2))
